  `remark` varchar(200) NOT NULL COMMENT '备注',
  `cur_bill` varchar(12) NOT NULL DEFAULT 'T' COMMENT 'T为当前有效账单，F为历史账单',
  `cur_receivable` decimal(10,2) DEFAULT NULL COMMENT '当期应收金额'
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

