-- ----------------------------
-- Table structure for business_purchase_apply
-- ----------------------------
DROP TABLE IF EXISTS `business_purchase_apply`;
CREATE TABLE `business_purchase_apply` (
  `apply_order_id` varchar(30) COLLATE utf8_bin NOT NULL COMMENT '订单号',
  `b_id` varchar(30) COLLATE utf8_bin NOT NULL COMMENT '业务Id',
  `store_id` varchar(30) COLLATE utf8_bin NOT NULL COMMENT '商户ID',
  `user_id` varchar(30) COLLATE utf8_bin DEFAULT NULL COMMENT '申请人id',
  `user_name` varchar(50) COLLATE utf8_bin DEFAULT NULL COMMENT '申请人姓名',
  `description` varchar(200) COLLATE utf8_bin NOT NULL COMMENT '申请说明',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `res_order_type` varchar(8) COLLATE utf8_bin NOT NULL COMMENT '出库类型 10000 入库 20000 出库 在t_dict表查看',
  `state` varchar(12) COLLATE utf8_bin NOT NULL COMMENT '申请状态',
  `status_cd` varchar(2) COLLATE utf8_bin NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考t_dict表，0, 在用 1失效',
  `operate` varchar(4) COLLATE utf8_bin NOT NULL COMMENT '数据状态，添加ADD，修改MOD 删除DEL',
  `end_user_name` varchar(50) COLLATE utf8_bin NOT NULL DEFAULT '无' COMMENT '物品使用人',
  `end_user_tel` varchar(11) COLLATE utf8_bin NOT NULL DEFAULT '无' COMMENT '物品使用人电话'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_bin;

