-- ----------------------------
-- Table structure for business_purchase_apply_detail
-- ----------------------------
DROP TABLE IF EXISTS `business_purchase_apply_detail`;
CREATE TABLE `business_purchase_apply_detail` (
  `apply_order_id` varchar(30) COLLATE utf8_bin NOT NULL COMMENT '订单号',
  `b_id` varchar(30) COLLATE utf8_bin NOT NULL COMMENT '业务ID',
  `res_id` varchar(30) COLLATE utf8_bin NOT NULL COMMENT '资源ID',
  `quantity` varchar(100) COLLATE utf8_bin NOT NULL COMMENT '数量',
  `remark` varchar(100) COLLATE utf8_bin DEFAULT NULL COMMENT '备注',
  `operate` varchar(4) COLLATE utf8_bin NOT NULL COMMENT '数据状态，添加ADD，修改MOD 删除DEL',
  `status_cd` varchar(2) COLLATE utf8_bin DEFAULT NULL,
  `price` decimal(9,2) DEFAULT NULL COMMENT '采购单价',
  `purchase_quantity` int(11) DEFAULT NULL COMMENT '采购数量',
  `purchase_remark` varchar(200) COLLATE utf8_bin DEFAULT NULL COMMENT '采购说明',
  `id` varchar(30) COLLATE utf8_bin NOT NULL COMMENT '主键ID',
  KEY `idx_apply_detail_id` (`apply_order_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_bin;

