-- ----------------------------
-- Table structure for contract
-- ----------------------------
DROP TABLE IF EXISTS `contract`;
CREATE TABLE `contract` (
  `contract_id` varchar(30) NOT NULL COMMENT '合同ID',
  `contract_code` varchar(30) NOT NULL COMMENT '合同编码',
  `contract_name` varchar(200) NOT NULL COMMENT '合同名称',
  `contract_type` varchar(30) NOT NULL COMMENT '合同类型',
  `obj_type` varchar(12) DEFAULT '1111' COMMENT '合同对象类型：3333 房屋 ，1111 没有合同对象',
  `obj_id` varchar(30) DEFAULT '-1' COMMENT '合同对象',
  `party_a` varchar(200) NOT NULL COMMENT '甲方',
  `party_b` varchar(200) NOT NULL COMMENT '乙方',
  `a_contacts` varchar(64) NOT NULL COMMENT '甲方联系人',
  `a_link` varchar(11) NOT NULL COMMENT '甲方联系电话',
  `b_contacts` varchar(64) NOT NULL COMMENT '乙方联系人',
  `b_link` varchar(11) NOT NULL COMMENT '乙方联系电话',
  `operator` varchar(64) NOT NULL COMMENT '经办人',
  `operator_link` varchar(11) NOT NULL COMMENT '经办人电话',
  `amount` decimal(10,2) DEFAULT NULL COMMENT '合同金额',
  `start_time` datetime NOT NULL COMMENT '合同开始时间',
  `end_time` datetime NOT NULL COMMENT '合同结束时间',
  `signing_time` datetime NOT NULL COMMENT '签订时间',
  `store_id` varchar(30) NOT NULL COMMENT '商户ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `state` varchar(12) NOT NULL COMMENT '11 待审核 22 审核通过 33 审核失败 44 手工停止',
  `state_desc` longtext COMMENT '审核意见',
  UNIQUE KEY `contract_id` (`contract_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of contract
-- ----------------------------

-- ----------------------------
-- Table structure for contract_attr
-- ----------------------------
DROP TABLE IF EXISTS `contract_attr`;
CREATE TABLE `contract_attr` (
  `attr_id` varchar(30) NOT NULL COMMENT '属性id',
  `contract_id` varchar(30) NOT NULL COMMENT '合同ID',
  `spec_cd` varchar(30) NOT NULL COMMENT '属性规格',
  `value` varchar(50) NOT NULL COMMENT '属性值',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `store_id` varchar(30) NOT NULL COMMENT '商户ID 分片ID',
  UNIQUE KEY `attr_id` (`attr_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of contract_attr
-- ----------------------------

-- ----------------------------
-- Table structure for contract_type
-- ----------------------------
DROP TABLE IF EXISTS `contract_type`;
CREATE TABLE `contract_type` (
  `contract_type_id` varchar(30) NOT NULL COMMENT 'ID',
  `type_name` varchar(200) NOT NULL COMMENT '合同类型名称',
  `audit` varchar(12) NOT NULL COMMENT '是否需要审核，1001 需要审核 2002 不需要审核 3003 需要admin审核  4004 需要 代理商审核',
  `is_default` varchar(12) NOT NULL DEFAULT 'F' COMMENT 'T 默认 F 自定义',
  `store_id` varchar(30) NOT NULL COMMENT '商户ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `remark` varchar(500) NOT NULL COMMENT '备注',
  PRIMARY KEY (`contract_type_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of contract_type
-- ----------------------------

-- ----------------------------
-- Table structure for contract_type_spec
-- ----------------------------
DROP TABLE IF EXISTS `contract_type_spec`;
CREATE TABLE `contract_type_spec` (
  `spec_cd` varchar(30) NOT NULL COMMENT '规格ID',
  `contract_type_id` varchar(30) NOT NULL COMMENT '合同类型ID',
  `store_id` varchar(30) NOT NULL COMMENT '商户ID',
  `spec_name` varchar(100) NOT NULL COMMENT '规格名称',
  `spec_holdplace` varchar(100) NOT NULL COMMENT '字段填写说明',
  `required` varchar(2) NOT NULL COMMENT '是否必填 Y 必填，N非必填',
  `spec_show` varchar(2) NOT NULL COMMENT '是否展示',
  `spec_value_type` varchar(12) NOT NULL COMMENT '1001 字符串 2002 整数 3003 金额 4004 日期 5005 时间',
  `spec_type` varchar(12) NOT NULL COMMENT '2233 input 3344 select 4455 日期',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `list_show` varchar(2) NOT NULL COMMENT '是否展示在list页面 Y 是 N 不是',
  PRIMARY KEY (`spec_cd`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of contract_type_spec
-- ----------------------------

