DROP TABLE IF EXISTS `contract_type_template`;
CREATE TABLE `contract_type_template` (
  `template_id` varchar(30) NOT NULL COMMENT '模板ID',
  `contract_type_id` varchar(30) NOT NULL COMMENT '合同类型ID',
  `store_id` varchar(30) NOT NULL COMMENT '商户ID',
  `context` longtext NOT NULL COMMENT '模板内容',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(12) NOT NULL DEFAULT '0' COMMENT '状态值',
  PRIMARY KEY (`template_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

