  UNIQUE KEY `ifd_id` (`ifd_id`) USING BTREE,
  KEY `ifd_fee_id` (`fee_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='费用导入明细表';

