-- ----------------------------
-- Table structure for pay_fee_audit
-- ----------------------------
DROP TABLE IF EXISTS `pay_fee_audit`;
CREATE TABLE `pay_fee_audit` (
  `audit_id` varchar(30) NOT NULL COMMENT '审核ID',
  `fee_id` varchar(30) NOT NULL COMMENT '费用ID',
  `community_id` varchar(30) NOT NULL COMMENT '小区分片',
  `fee_detail_id` varchar(30) NOT NULL COMMENT '消费ID',
  `state` varchar(12) NOT NULL COMMENT '审核状态 1010 待审核 2020 审核通过 3030 未审核',
  `message` varchar(500) DEFAULT NULL COMMENT '审核意见',
  `audit_user_id` varchar(30) NOT NULL COMMENT '审核人',
  `audit_user_name` varchar(64) NOT NULL COMMENT '审核人名称',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  PRIMARY KEY (`audit_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of pay_fee_audit
-- ----------------------------

-- ----------------------------
-- Table structure for pay_fee_config
-- ----------------------------
DROP TABLE IF EXISTS `pay_fee_config`;
CREATE TABLE `pay_fee_config` (
  `config_id` varchar(30) NOT NULL COMMENT '费用ID',
  `b_id` varchar(30) NOT NULL COMMENT '业务Id',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `fee_type_cd` varchar(12) NOT NULL COMMENT '费用类型，物业费，停车费',
  `square_price` decimal(7,2) NOT NULL COMMENT '每平米收取的单价',
  `additional_amount` decimal(10,2) NOT NULL COMMENT '附加费用',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `is_default` varchar(12) NOT NULL DEFAULT 'F' COMMENT '默认费用 只能修改 不能做删除 T 标识是默认 F 不是默认',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `fee_flag` varchar(12) NOT NULL DEFAULT '1003006' COMMENT '费用标识 1003006 为周期性费用 2006012 为一次性费用',
  `fee_name` varchar(100) NOT NULL DEFAULT '未知' COMMENT '费用项名称',
  `computing_formula` varchar(12) NOT NULL DEFAULT '1001' COMMENT '计算公式 1001 面积*单价+附加费 2002 固定费用',
  `bill_type` varchar(12) NOT NULL DEFAULT '004' COMMENT '出账类型',
  `payment_cycle` varchar(12) NOT NULL DEFAULT '1' COMMENT '缴费周期',
  `payment_cd` varchar(12) NOT NULL DEFAULT '1200' COMMENT '付费类型',
  UNIQUE KEY `config_id` (`config_id`) USING BTREE,
  UNIQUE KEY `config_id_2` (`config_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of pay_fee_config
-- ----------------------------

-- ----------------------------
-- Table structure for pay_fee_config_discount
-- ----------------------------
DROP TABLE IF EXISTS `pay_fee_config_discount`;
CREATE TABLE `pay_fee_config_discount` (
  `config_discount_id` varchar(30) NOT NULL COMMENT '费用项折扣ID',
  `config_id` varchar(30) NOT NULL COMMENT '费用项ID',
  `discount_id` varchar(30) NOT NULL COMMENT '折扣ID',
  `community_id` varchar(30) NOT NULL COMMENT '分片小区ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态',
  PRIMARY KEY (`config_discount_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of pay_fee_config_discount
-- ----------------------------

-- ----------------------------
-- Table structure for pay_fee_detail
-- ----------------------------
DROP TABLE IF EXISTS `pay_fee_detail`;
CREATE TABLE `pay_fee_detail` (
  `detail_id` varchar(30) NOT NULL COMMENT '费用明细ID',
  `b_id` varchar(30) NOT NULL COMMENT '业务Id',
  `fee_id` varchar(30) NOT NULL COMMENT '费用ID',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `cycles` decimal(9,2) NOT NULL COMMENT '周期，以月为单位',
  `receivable_amount` decimal(10,2) NOT NULL COMMENT '应收金额',
  `received_amount` decimal(10,2) NOT NULL COMMENT '应收金额',
  `prime_rate` decimal(3,2) NOT NULL COMMENT '打折率',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `state` varchar(4) DEFAULT '1400' COMMENT '用于退费状态参考字典表',
  `start_time` datetime DEFAULT NULL COMMENT '费用开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '费用结束时间',
  UNIQUE KEY `detail_id` (`detail_id`) USING BTREE,
  KEY `i_pfd_fee_id` (`fee_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of pay_fee_detail
-- ----------------------------

-- ----------------------------
-- Table structure for pay_fee_detail_discount
-- ----------------------------
DROP TABLE IF EXISTS `pay_fee_detail_discount`;
CREATE TABLE `pay_fee_detail_discount` (
  `detail_discount_id` varchar(30) NOT NULL COMMENT '明细优惠',
  `b_id` varchar(30) NOT NULL COMMENT '业务ID',
  `fee_id` varchar(30) NOT NULL COMMENT '费用ID',
  `detail_id` varchar(30) NOT NULL COMMENT '费用明细ID',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `discount_id` varchar(30) NOT NULL COMMENT '折扣ID',
  `discount_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '折扣金额',
  `remark` varchar(512) DEFAULT NULL COMMENT '优惠说明',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态',
  PRIMARY KEY (`detail_discount_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of pay_fee_detail_discount
