-- ----------------------------
-- Table structure for prestore_fee
-- ----------------------------
DROP TABLE IF EXISTS `prestore_fee`;
CREATE TABLE `prestore_fee` (
  `prestore_fee_id` varchar(30) NOT NULL COMMENT '预存费用id',
  `prestore_fee_type` varchar(4) DEFAULT NULL COMMENT '预存费用类型 水费8003、电费8004',
  `room_id` varchar(30) DEFAULT NULL COMMENT '预存对象id,预存至房屋',
  `prestore_fee_obj_type` varchar(4) DEFAULT NULL COMMENT '预存对象类型  3333房屋 6666车位',
  `prestore_fee_amount` varchar(8) DEFAULT NULL COMMENT '预存金额',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `remark` varchar(100) DEFAULT NULL COMMENT '备注',
  `community_id` varchar(30) DEFAULT NULL COMMENT '小区ID',
  `reason` varchar(255) DEFAULT NULL COMMENT '原因',
  `use_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '使用时间',
  `state` varchar(4) DEFAULT NULL COMMENT '1001未使用 2002已使用',
  `status_cd` varchar(2) DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  PRIMARY KEY (`prestore_fee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

