  `store_id` varchar(30) NOT NULL COMMENT '商户ID',
  `app_type` varchar(12) NOT NULL COMMENT '认证类型',
  `open_id` varchar(128) NOT NULL COMMENT '开放ID',
  `state` varchar(12) NOT NULL DEFAULT '1001' COMMENT '1001 未认证 2002 已认证',
  `open_name` varchar(128) DEFAULT NULL COMMENT '认证名字',
