  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `member_id` varchar(50) NOT NULL COMMENT '成员ID',
  `member_type_cd` varchar(12) NOT NULL COMMENT '成员类型见 community_member_type表',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(4) NOT NULL COMMENT '数据状态',
  `audit_status_cd` varchar(4) NOT NULL DEFAULT '0000' COMMENT '审核状态',
  UNIQUE KEY `community_member_id` (`community_member_id`) USING BTREE,
  KEY `idx_s_community_member_id` (`community_id`) USING BTREE,
  KEY `idx_s_community_member_b_id` (`b_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

