  `photo` varchar(100) NOT NULL COMMENT '照片',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  UNIQUE KEY `community_photo_id` (`community_photo_id`) USING BTREE,
  KEY `idx_community_photo_b_id` (`b_id`) USING BTREE,
  KEY `idx_community_photo_community_id` (`community_id`) USING BTREE,
  KEY `idx_community_photo_community_photo_id` (`community_photo_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

