-- ----------------------------
-- Table structure for u_user_login
-- ----------------------------
DROP TABLE IF EXISTS `u_user_login`;
CREATE TABLE `u_user_login` (
  `login_id` varchar(30) NOT NULL COMMENT '登录ID',
  `user_id` varchar(30) NOT NULL COMMENT '用户ID',
  `user_name` varchar(64) NOT NULL COMMENT '用户名称',
  `password` varchar(128) NOT NULL COMMENT '登录密码',
  `login_time` datetime NOT NULL COMMENT '登录时间',
  `source` varchar(12) NOT NULL DEFAULT 'WEB' COMMENT '登录来源',
  `token` longtext COMMENT '登录token记录',
  KEY `i_ul_login_time` (`login_time`) USING BTREE,
  KEY `i_ul_user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

