-- Table structure for wechat_attr
-- ----------------------------
DROP TABLE IF EXISTS `wechat_attr`;
CREATE TABLE `wechat_attr` (
  `appid` varchar(200) COLLATE utf8_bin NOT NULL,
  `attr_id` varchar(30) COLLATE utf8_bin DEFAULT NULL,
  `spec_cd` varchar(12) COLLATE utf8_bin NOT NULL,
  `value` varchar(100) COLLATE utf8_bin NOT NULL,
  `b_id` varchar(30) COLLATE utf8_bin NOT NULL,
  `store_id` varchar(0) COLLATE utf8_bin NOT NULL,
  `create_time` datetime NOT NULL,
  `status_cd` varchar(1) COLLATE utf8_bin NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_bin;

