INSERT INTO `contract_type_template` VALUES ('822020102729480186', '812020102710590185', '402019032924930007', '<p>甲方</p><p>乙方</p><p><br></p><p>条例1</p><p>条例2</p><p>条例3</p>', '2020-10-27 19:50:32', '0');
INSERT INTO `contract_type_template` VALUES ('822020111388130378', '812020111300750377', '402020102999010220', '<p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">甲方（出租方）：_________身份证号码：_________</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　乙方（承租方）：_________身份证号码：_________</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　现经甲乙双方充分了解、协商，一致达成如下租房合同：</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　一、 房屋的坐落、面积、装修及设施、设备：</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　二、租赁期限：_________，即年月日至年月日。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　三、租金及交纳时间：每月元，乙方应每月付一次，先付后住。第一次乙方应于甲方将房屋交付同时，将房租付给甲方；第二次及以后付租金，乙方应提前一个月付清。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　四、租房押金：乙方应于签约同时付给甲方押金元，到期结算，多余归还。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　五、租赁期间的其他约定事项：</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　1、甲乙双方应提供真实有效的房产证、身份证等证件。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　2、甲方提供完好的房屋、设施、设备，乙方应注意爱护，不得破坏房屋装修、结构及设施、设备，否则应按价赔偿。如使用中有非人为损坏，应由甲方修理。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　3、 水、电、煤气、电话、网络、有线电视等的使用费及物业、电梯、卫生费等所有费用都由乙方支付。入住日抄见：水度，电度，煤气度。所有费用乙方应按时付清。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　4、 房屋只限乙方使用，乙方不得私自转租、改变使用性质或供非法用途。租下本房后，乙方应立即办好租赁登记、暂住人口登记等手续。若发生非法事件，乙方自负后果。在租赁期限内，甲方确需提前收回房屋时，应当事先商得乙方同意，给乙方造成损失的，应当予以赔偿。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　5、 合同一经签订，双方都不得提前解除。租赁期内，如遇不可抗力因素导致无法继续履行本合同的，本合同自然终止，双方互不承担违约责任。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　6、 甲乙双方约定，乙方如需开具房租发票，因此产生的税费由乙方支付。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　7、 此合同未尽事宜，双方可协商解决，并作出补充条款，补充条款与本合同有同等效力。双方如果出现纠纷，先友好协商，协商不成的，由人<a title=\"民法\" href=\"http://www.chinalawedu.com/sifakaoshi/ziliao/minfa/\" target=\"_blank\" class=\"bule\" style=\"outline: none; color: rgb(0, 0, 255);\">民法</a>院裁定。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　8、 本合同经签字（盖章）生效。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　9、其他约定事项：</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　六、违约责任：</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　甲乙双方中任一方有违约情况发生的，违约方应向守约方支付违约金，违约金为元，损失超过违约金时，须另行追加赔偿。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　七、本合同一式两份，甲乙两方各执一份，具有同等　<a title=\"法律\" href=\"http://www.chinalawedu.com/\" target=\"_blank\" class=\"bule\" style=\"outline: none; color: rgb(0, 0, 255);\">法律</a>效力。</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　甲方（签字）：__________________乙方（签字）：____________________</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 10px 0px 0px; color: rgb(51, 51, 51); font-family: 宋体, Helvetica, Tahoma, arial, sans-serif; font-size: 14px;\">　　联系电话：____________________联系电话：______________________</p>', '2020-11-13 16:08:47', '0');
