INSERT INTO `unitem_log` VALUES ('2020200922165015856', '1020200922223115855', '2020-09-22 17:57:22', 'store-service', '{\"afterValue\":[{\"store_id\":\"\'402019032924930007\'\",\"create_time\":\"\'2020-09-21 23:42:05\'\",\"status_cd\":\"\'0\'\",\"context\":\"\'<div class=\\\"para\\\" label-module=\\\"para\\\" style=\\\"font-size: 14px; overflow-wrap: break-word; color: rgb(51, 51, 51); margin-bottom: 15px; text-indent: 2em; line-height: 24px; zoom: 1; font-family: arial, 宋体, sans-serif;\\\">合同是适应私有制的商品经济的客观要求而出现的，是<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E5%95%86%E5%93%81%E4%BA%A4%E6%8D%A2\\\" style=\\\"color: rgb(19, 110, 194);\\\">商品交换</a>在法律上的表现形式。商品生产产生后，为了交换的安全和信誉，人们在长期的交换实践中逐渐形成了许多关于交换的习惯和仪式。这些商品交换的习惯和仪式便逐渐成为调整商品交换的一般规则。随着私有制的确立和国家的产生，统治阶级为了维护私有制和正常的经济秩序，把有利于他们的商品交换的习惯和规则用法律形式加以规定，并以国家强制力保障实行。于是商品交换的合同法律形成便应运而生了。古罗马时期合同就受到人们的重视。签订合同必须经过规定的方式，才能发生<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E6%B3%95%E5%BE%8B%E6%95%88%E5%8A%9B\\\" style=\\\"color: rgb(19, 110, 194);\\\">法律效力</a>。如果合同仪式的术语和动作被遗漏任何一个细节，就会导致整个<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E5%90%88%E5%90%8C%E6%97%A0%E6%95%88\\\" style=\\\"color: rgb(19, 110, 194);\\\">合同无效</a>。随着商品经济的发展，这种繁琐的形式直接影响到商品交换的发展。在理论和实践上，<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E7%BD%97%E9%A9%AC%E6%B3%95\\\" style=\\\"color: rgb(19, 110, 194);\\\">罗马法</a>逐渐克服了缔约中的形式主义。要物合同和合意合同的出现，标志着罗马法从重视形式转为重视缔约人的意志，从而使商品交换从繁琐的形式中解脱出来，并且成为现代合同自由观念的历史渊源。</div><div class=\\\"para\\\" label-module=\\\"para\\\" style=\\\"font-size: 14px; overflow-wrap: break-word; color: rgb(51, 51, 51); margin-bottom: 15px; text-indent: 2em; line-height: 24px; zoom: 1; font-family: arial, 宋体, sans-serif;\\\">合同制在中国古代也有悠久的历史。《<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E5%91%A8%E7%A4%BC/1639127\\\" data-lemmaid=\\\"1639127\\\" style=\\\"color: rgb(19, 110, 194);\\\">周礼</a>》对早期合同的形式有较为详细的规定。判书、质剂、<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E5%82%85%E5%88%AB\\\" style=\\\"color: rgb(19, 110, 194);\\\">傅别</a>、书契等都是古代合同的书面形式。经过唐、宋、元、明、清各代，法律对合同的规定也越来越系统。</div><div class=\\\"para\\\" label-module=\\\"para\\\" style=\\\"font-size: 14px; overflow-wrap: break-word; color: rgb(51, 51, 51); margin-bottom: 15px; text-indent: 2em; line-height: 24px; zoom: 1; font-family: arial, 宋体, sans-serif;\\\">还有一种说法，现代的合同都写有一式两份，因为以前民间订制合同时就是一张纸，写好后从中间撕开，一人拿一半，有争执的时候再合起来，所以就有了合同和一式两份的说法。w</div>\'\",\"contract_type_id\":\"\'812020091861220002\'\",\"template_id\":\"\'822020092185630008\'\"}],\"preValue\":[{\"store_id\":\"\'402019032924930007\'\",\"create_time\":\"\'2020-09-21 23:42:05\'\",\"status_cd\":\"\'0\'\",\"context\":\"\'<div class=\\\"para\\\" label-module=\\\"para\\\" style=\\\"font-size: 14px; overflow-wrap: break-word; color: rgb(51, 51, 51); margin-bottom: 15px; text-indent: 2em; line-height: 24px; zoom: 1; font-family: arial, 宋体, sans-serif;\\\">合同是适应私有制的商品经济的客观要求而出现的，是<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E5%95%86%E5%93%81%E4%BA%A4%E6%8D%A2\\\" style=\\\"color: rgb(19, 110, 194);\\\">商品交换</a>在法律上的表现形式。商品生产产生后，为了交换的安全和信誉，人们在长期的交换实践中逐渐形成了许多关于交换的习惯和仪式。这些商品交换的习惯和仪式便逐渐成为调整商品交换的一般规则。随着私有制的确立和国家的产生，统治阶级为了维护私有制和正常的经济秩序，把有利于他们的商品交换的习惯和规则用法律形式加以规定，并以国家强制力保障实行。于是商品交换的合同法律形成便应运而生了。古罗马时期合同就受到人们的重视。签订合同必须经过规定的方式，才能发生<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E6%B3%95%E5%BE%8B%E6%95%88%E5%8A%9B\\\" style=\\\"color: rgb(19, 110, 194);\\\">法律效力</a>。如果合同仪式的术语和动作被遗漏任何一个细节，就会导致整个<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E5%90%88%E5%90%8C%E6%97%A0%E6%95%88\\\" style=\\\"color: rgb(19, 110, 194);\\\">合同无效</a>。随着商品经济的发展，这种繁琐的形式直接影响到商品交换的发展。在理论和实践上，<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E7%BD%97%E9%A9%AC%E6%B3%95\\\" style=\\\"color: rgb(19, 110, 194);\\\">罗马法</a>逐渐克服了缔约中的形式主义。要物合同和合意合同的出现，标志着罗马法从重视形式转为重视缔约人的意志，从而使商品交换从繁琐的形式中解脱出来，并且成为现代合同自由观念的历史渊源。</div><div class=\\\"para\\\" label-module=\\\"para\\\" style=\\\"font-size: 14px; overflow-wrap: break-word; color: rgb(51, 51, 51); margin-bottom: 15px; text-indent: 2em; line-height: 24px; zoom: 1; font-family: arial, 宋体, sans-serif;\\\">合同制在中国古代也有悠久的历史。《<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E5%91%A8%E7%A4%BC/1639127\\\" data-lemmaid=\\\"1639127\\\" style=\\\"color: rgb(19, 110, 194);\\\">周礼</a>》对早期合同的形式有较为详细的规定。判书、质剂、<a target=\\\"_blank\\\" href=\\\"https://baike.baidu.com/item/%E5%82%85%E5%88%AB\\\" style=\\\"color: rgb(19, 110, 194);\\\">傅别</a>、书契等都是古代合同的书面形式。经过唐、宋、元、明、清各代，法律对合同的规定也越来越系统。</div><div class=\\\"para\\\" label-module=\\\"para\\\" style=\\\"font-size: 14px; overflow-wrap: break-word; color: rgb(51, 51, 51); margin-bottom: 15px; text-indent: 2em; line-height: 24px; zoom: 1; font-family: arial, 宋体, sans-serif;\\\">还有一种说法，现代的合同都写有一式两份，因为以前民间订制合同时就是一张纸，写好后从中间撕开，一人拿一半，有争执的时候再合起来，所以就有了合同和一式两份的说法。</div>\'\",\"contract_type_id\":\"\'812020091861220002\'\",\"template_id\":\"\'822020092185630008\'\"}]}', '0');
