INSERT INTO `unitem_log` VALUES ('2020201125370422126', '1020201125290222125', '2020-11-25 20:06:46', 'store-service', '{\"afterValue\":[{\"store_id\":\"\'402019032924930007\'\",\"type_name\":\"\'租赁合同类型\'\",\"create_time\":\"\'2020-09-18 17:24:25\'\",\"status_cd\":\"\'0\'\",\"audit\":\"\'1001\'\",\"contract_type_id\":\"\'812000000000000001\'\",\"remark\":\"\'租赁合同统一模板\'\",\"is_default\":\"\'T\'\"}],\"preValue\":[{\"store_id\":\"\'402019032924930007\'\",\"type_name\":\"\'租赁合同\'\",\"create_time\":\"\'2020-09-18 17:24:25\'\",\"status_cd\":\"\'0\'\",\"audit\":\"\'1001\'\",\"contract_type_id\":\"\'812000000000000001\'\",\"remark\":\"\'租赁合同统一模板\'\",\"is_default\":\"\'T\'\"}]}', '0');
INSERT INTO `unitem_log` VALUES ('2020201125383322149', '1020201125621522148', '2020-11-25 20:14:35', 'store-service', '{\"afterValue\":[{\"store_id\":\"\'402019032924930007\'\",\"create_time\":\"\'2020-10-12 13:42:52\'\",\"status_cd\":\"\'0\'\",\"context\":\"\'<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <b>商铺租赁合同</b></p><p>出租方（以下简称甲方）__________________ </p><p>承租方（以下简称乙方）__________________ </p><p>甲乙双方本着诚实信用，互利互惠的原则，根据《中华人民共和国合同法》法律，法规的规定，就乙方租赁甲方房屋相关事宜达成本合同，以兹共同遵守：</p><p>第一条：租赁房屋坐落地址及商铺面积商铺坐落地址：________________________.商铺面积约______平方米。</p><p>第二条：租赁用途：商铺使用。</p><p>第三条：租赁期限</p><p>1、租期五年：______年_____月_____日至______年_____月_____日。</p><p>2、续租：本合同约定租赁期满后，如果甲方同意乙方可以继续承租本合同项下房屋，续约期内的租金，由双方根据当时的市场价格协商确定，在同等条件下乙方有优先权，续约期内双方的权利义务除双方另有约定外均适用本合同相应规定。</p><p>第四条：租金和支付方式及租金交纳期限：</p><p>1、租赁金额：每年___________元。</p><p>2、付款方式：上交款。甲乙双方自签订本合同之日，乙方一次性向甲方支付全年的房租，第二年至第五年的房租要提前一个月交。</p><p>3、乙方必须按照约定向甲方交纳租金。到期不交视同违约，违约金壹拾万元整。</p><p>第五条：房屋的附属设施及费用的承担</p><p>1、承租区域内设施的使用乙方向甲方或第三物业管理者支付水、电费、房产、土地使用税及其他产生的直接费用。收费标准按相关标准的执行。</p><p>2、使用该房屋进行商业活动产生的其他各项费用均由乙方缴纳，（其中包括乙方自己申请安装电话、宽带、有线电视等设备的费用）</p><p>3、租赁期间，由乙方导致租赁房屋的质量或房屋内外部设施损毁，包括房内外防水、门窗、水电等，维修费由乙方负责。</p><p>第六条：租赁期间房屋修缮</p><p>1、出租方房屋交给承租方后，承租方在使用期间的装修及修缮有承租方自行负责。如承租方不再使用出租的房屋后，承租方不得破坏已装修固定的设施及房屋构架。 </p><p>2、承租方装修过程中需改变房屋原貌或改变主要结构时得向甲方申请，得到甲方及有关部门领导同意后方可施工，施工单位要有资质的单位，并向有关部门备案，施工期间和施工后出现任何事情与甲方无关。如未经同意私自施工，甲方有权提前终止合同，并赔偿损失。造成后果由双方协商或移交法律部门追究法律责任。 </p><p>  第七条：甲方权利和义务 </p><p>  1、有权按本合同规定向乙方收取租金及其他各项费用或逾期违约金。 </p><p>  2、监督乙方正确使用房屋、并保证房屋内外各类设施在乙方进场时能正常使用。   3、甲方不承担乙方的经营风险及责任。 </p><p>  4、在乙方有以下行为时：擅自将房屋整修转租、转让或转借；利用承租房进行违规及违章经营和非法活动时，损害公共利益或甲方利益时；拖欠租金的行为。甲方有权提前终止合同，并提出赔偿。乙方租赁期间内可以部分面积招租或招商，甲方不得以任何理由干涉。 </p><p>  5、与乙方另签订消防安全协议书此合同附件，监督乙方安全使用房屋，针对发现乙方的安全有权要求限期整改。 </p><p>  6、在乙方办理工商、税务等手续时，甲方应为乙方提供房屋的相关证明文件。   7、在乙方没有违反使用水、电时，甲方应保证商铺正常用水用电。   第八条：乙方权利和义务 </p><p>  1、按照房屋的使用用途，使用租赁房屋开展正常经营活动，不受甲方干涉，但乙方不得擅自改造用途。   2、确保消防安全，如果因乙方使用房屋或经乙方装修房屋出现并造成人身财产损害时，均由乙方承担全部赔偿责任。 </p><p>  3、按照交纳房屋租金及其他费用。 </p><p>  4、不擅自拆改房屋构造，不在租赁房屋内从事违法活动。 </p><p>  5、甲乙双方在经营过程中如因对方原因造成双方无法正常经营，所带来的一切损失由责任方承担。并负责损失的赔偿。 </p><p>第九条：违约责任和合同终止的赔偿措施 </p><p>  1、若租赁房屋因不可抗力的自然灾害导致损毁和造成承租人的任何损失或无法使用房屋时，双方互不承担责任，合同终止。</p><p>&nbsp; &nbsp;2、若甲乙双方在没有违反本合同的情况下提前解除合同或租给他人，视为单方违约、应赔偿对方一切经济损失。并有壹拾万元的违约金。   </p><p>第十条：争议的解决办法 </p><p>  本合同在履行中如发生其他争议，双方应友好协商解决，协商不成时，任何一方均可以向人民法院起诉。 </p><p>第十一条：本合同如有未尽事宜，按《中华人民共和国合同法》的有关规定，经甲、乙双方共同协商，作出补充规定，补充规定与本合同具有同等效力。 </p><p>第十二条：本合同至双方签字盖章后生效，本合同_____页，一式两份，甲乙双方各执一份，均有同等法律效力。 </p><p>  出租方（盖章）_____________   承租方（盖章）_____________  </p><p>&nbsp; &nbsp;法定代表人（签字）_________   法定代表人（签字）_________   </p><p>&nbsp; &nbsp;联系电话：__________________   联系电话：__________________   </p><p>&nbsp; &nbsp;联系地址：__________________   联系地址：__________________   </p><p>&nbsp; &nbsp;身份证号：__________________   身份证号：__________________   </p><p>&nbsp; &nbsp;______年_____月_____日   ______年_____月_____日</p><p><br></p><p><br></p>\'\",\"contract_type_id\":\"\'812000000000000001\'\",\"template_id\":\"\'822020101296040053\'\"}],\"preValue\":[{\"store_id\":\"\'402019032924930007\'\",\"create_time\":\"\'2020-10-12 13:42:52\'\",\"status_cd\":\"\'0\'\",\"context\":\"\'<p>商铺租赁合同</p><p>出租方（以下简称甲方）__________________ </p><p>承租方（以下简称乙方）__________________ </p><p>甲乙双方本着诚实信用，互利互惠的原则，根据《中华人民共和国合同法》法律，法规的规定，就乙方租赁甲方房屋相关事宜达成本合同，以兹共同遵守：</p><p>第一条：租赁房屋坐落地址及商铺面积商铺坐落地址：________________________.商铺面积约______平方米。</p><p>第二条：租赁用途：商铺使用。</p><p>第三条：租赁期限</p><p>1、租期五年：______年_____月_____日至______年_____月_____日。</p><p>2、续租：本合同约定租赁期满后，如果甲方同意乙方可以继续承租本合同项下房屋，续约期内的租金，由双方根据当时的市场价格协商确定，在同等条件下乙方有优先权，续约期内双方的权利义务除双方另有约定外均适用本合同相应规定。</p><p>第四条：租金和支付方式及租金交纳期限：</p><p>1、租赁金额：每年___________元。</p><p>2、付款方式：上交款。甲乙双方自签订本合同之日，乙方一次性向甲方支付全年的房租，第二年至第五年的房租要提前一个月交。</p><p>3、乙方必须按照约定向甲方交纳租金。到期不